import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const DB_STORAGE_DIR = path.resolve(__dirname, '../../data');
const DB_STORAGE_FILE = path.join(DB_STORAGE_DIR, 'medicare_db.json');

// Global in-memory storage for models
const collections = {};
const models = {};

function ensureStorage() {
  try {
    if (!fs.existsSync(DB_STORAGE_DIR)) {
      fs.mkdirSync(DB_STORAGE_DIR, { recursive: true });
    }
    if (fs.existsSync(DB_STORAGE_FILE)) {
      const data = JSON.parse(fs.readFileSync(DB_STORAGE_FILE, 'utf8'));
      Object.assign(collections, data);
    }
  } catch (e) {
    console.warn('[DB Storage] Initializing empty storage:', e.message);
  }
}

function persistStorage() {
  try {
    if (!fs.existsSync(DB_STORAGE_DIR)) {
      fs.mkdirSync(DB_STORAGE_DIR, { recursive: true });
    }
    fs.writeFileSync(DB_STORAGE_FILE, JSON.stringify(collections, null, 2), 'utf8');
  } catch (e) {
    console.error('[DB Storage] Failed to persist data:', e.message);
  }
}

ensureStorage();

function generateObjectId() {
  const timestamp = Math.floor(Date.now() / 1000).toString(16).padStart(8, '0');
  const random = Math.floor(Math.random() * 0xffffffffffff).toString(16).padStart(12, '0');
  const counter = Math.floor(Math.random() * 0xffff).toString(16).padStart(4, '0');
  return `${timestamp}${random}${counter}`;
}

export class Schema {
  constructor(definition, options = {}) {
    this.definition = definition;
    this.options = options;
    this.methods = {};
    this.statics = {};
    this.indexes = [];
  }

  index(fields, options = {}) {
    this.indexes.push({ fields, options });
  }
}

Schema.Types = {
  ObjectId: 'ObjectId',
  Mixed: 'Mixed',
  String,
  Number,
  Boolean,
  Date,
  Array
};

function matchesFilter(item, filter) {
  if (!filter || Object.keys(filter).length === 0) return true;

  if (filter.$or && Array.isArray(filter.$or)) {
    const orMatches = filter.$or.some(subFilter => matchesFilter(item, subFilter));
    if (!orMatches) return false;
  }

  for (const [key, expected] of Object.entries(filter)) {
    if (key === '$or') continue;

    let actual = item[key];
    if (key === '_id' || key === 'id') {
      actual = String(item._id || item.id);
    }

    if (expected === null || expected === undefined) {
      if (actual !== null && actual !== undefined) return false;
      continue;
    }

    if (typeof expected === 'object' && !(expected instanceof RegExp) && !(expected instanceof Date)) {
      // Check operators
      if (expected.$in && Array.isArray(expected.$in)) {
        const inMatch = expected.$in.some(val => String(val) === String(actual));
        if (!inMatch) return false;
        continue;
      }
      if (expected.$ne !== undefined) {
        if (String(actual) === String(expected.$ne)) return false;
        continue;
      }
      if (expected.$gte !== undefined) {
        if (actual < expected.$gte) return false;
        continue;
      }
      if (expected.$lte !== undefined) {
        if (actual > expected.$lte) return false;
        continue;
      }
      if (expected.$regex !== undefined) {
        const flags = expected.$options || '';
        const reg = new RegExp(expected.$regex, flags);
        if (!reg.test(String(actual || ''))) return false;
        continue;
      }
    }

    if (expected instanceof RegExp) {
      if (!expected.test(String(actual || ''))) return false;
      continue;
    }

    // Direct comparison
    if (String(actual) !== String(expected)) {
      return false;
    }
  }

  return true;
}

class Document {
  constructor(data, modelInstance) {
    this._model = modelInstance;
    Object.assign(this, data);
    if (!this._id) {
      this._id = generateObjectId();
    }
    this.id = this._id;

    // Attach schema methods
    if (modelInstance.schema?.methods) {
      for (const [methodName, fn] of Object.entries(modelInstance.schema.methods)) {
        this[methodName] = fn.bind(this);
      }
    }
  }

  toObject() {
    const copy = { ...this };
    delete copy._model;
    return copy;
  }

  toJSON() {
    const copy = this.toObject();
    if (this._model.schema?.options?.toJSON?.transform) {
      this._model.schema.options.toJSON.transform(this, copy);
    }
    return copy;
  }

  async save() {
    const col = collections[this._model.modelName];
    this.updatedAt = new Date();

    // Check unique indexes
    this._model._checkUniqueIndexes(this, this._id);

    const idx = col.findIndex(x => String(x._id) === String(this._id));
    const obj = this.toObject();
    if (idx >= 0) {
      col[idx] = obj;
    } else {
      if (!obj.createdAt) obj.createdAt = new Date();
      col.push(obj);
    }
    persistStorage();
    return this;
  }
}

class Query {
  constructor(modelInstance, operation, filter, extra) {
    this.model = modelInstance;
    this.operation = operation;
    this.filter = filter || {};
    this.extra = extra;
    this._populates = [];
    this._sort = null;
    this._skip = 0;
    this._limit = Infinity;
    this._select = null;
  }

  populate(path, select) {
    this._populates.push({ path, select });
    return this;
  }

  sort(sortObj) {
    this._sort = sortObj;
    return this;
  }

  skip(n) {
    this._skip = Number(n) || 0;
    return this;
  }

  limit(n) {
    this._limit = Number(n) || Infinity;
    return this;
  }

  select(fields) {
    this._select = fields;
    return this;
  }

  async exec() {
    const col = collections[this.model.modelName] || [];

    if (this.operation === 'countDocuments') {
      return col.filter(item => matchesFilter(item, this.filter)).length;
    }

    if (this.operation === 'exists') {
      const found = col.find(item => matchesFilter(item, this.filter));
      return found ? { _id: found._id } : null;
    }

    if (this.operation === 'findOne' || this.operation === 'findById') {
      const match = col.find(item => matchesFilter(item, this.filter));
      if (!match) return null;
      const doc = new Document(JSON.parse(JSON.stringify(match)), this.model);
      await this._applyPopulates([doc]);
      return doc;
    }

    if (this.operation === 'find') {
      let results = col.filter(item => matchesFilter(item, this.filter));

      // Sorting
      if (this._sort) {
        results.sort((a, b) => {
          for (const [k, dir] of Object.entries(this._sort)) {
            const va = a[k];
            const vb = b[k];
            if (va < vb) return dir === -1 ? 1 : -1;
            if (va > vb) return dir === -1 ? -1 : 1;
          }
          return 0;
        });
      }

      // Skip & Limit
      if (this._skip > 0) {
        results = results.slice(this._skip);
      }
      if (this._limit < Infinity) {
        results = results.slice(0, this._limit);
      }

      const docs = results.map(r => new Document(JSON.parse(JSON.stringify(r)), this.model));
      await this._applyPopulates(docs);
      return docs;
    }

    return null;
  }

  then(resolve, reject) {
    return this.exec().then(resolve, reject);
  }

  async _applyPopulates(docs) {
    for (const pop of this._populates) {
      const field = pop.path;
      for (const doc of docs) {
        const refId = doc[field];
        if (!refId) continue;

        // Try to locate referenced doc across all collections
        let foundRef = null;
        for (const [colName, items] of Object.entries(collections)) {
          const match = items.find(i => String(i._id) === String(refId) || String(i.id) === String(refId));
          if (match) {
            foundRef = { ...match };
            break;
          }
        }

        if (foundRef) {
          if (pop.select) {
            const allowed = pop.select.split(' ').filter(Boolean);
            const filteredRef = { _id: foundRef._id, id: foundRef._id };
            allowed.forEach(f => {
              if (foundRef[f] !== undefined) filteredRef[f] = foundRef[f];
            });
            doc[field] = filteredRef;
          } else {
            doc[field] = foundRef;
          }
        }
      }
    }
  }
}

class Model {
  constructor(name, schema) {
    this.modelName = name;
    this.schema = schema;
    if (!collections[name]) {
      collections[name] = [];
    }
  }

  _checkUniqueIndexes(docData, excludeId = null) {
    const col = collections[this.modelName] || [];

    // Check unique fields defined in schema
    if (this.schema?.definition) {
      for (const [key, def] of Object.entries(this.schema.definition)) {
        if (def && typeof def === 'object' && def.unique) {
          const val = docData[key];
          if (val !== undefined && val !== null) {
            const conflict = col.find(
              x => String(x[key]).toLowerCase() === String(val).toLowerCase() && String(x._id) !== String(excludeId)
            );
            if (conflict) {
              const err = new Error(`Duplicate value for field: ${key}`);
              err.code = 11000;
              err.keyValue = { [key]: val };
              throw err;
            }
          }
        }
      }
    }

    // Check compound unique indexes
    if (this.schema?.indexes) {
      for (const idx of this.schema.indexes) {
        if (idx.options?.unique) {
          const fields = Object.keys(idx.fields);
          // Check partial filter
          const filter = idx.options.partialFilterExpression;
          if (filter && !matchesFilter(docData, filter)) {
            continue;
          }

          const conflict = col.find(item => {
            if (excludeId && String(item._id) === String(excludeId)) return false;
            if (filter && !matchesFilter(item, filter)) return false;
            return fields.every(f => String(item[f]) === String(docData[f]));
          });

          if (conflict) {
            const err = new Error('Duplicate key error for compound unique index');
            err.code = 11000;
            err.keyValue = {};
            fields.forEach(f => {
              err.keyValue[f] = docData[f];
            });
            throw err;
          }
        }
      }
    }
  }

  async deleteMany(filter = {}) {
    const col = collections[this.modelName];
    if (Object.keys(filter).length === 0) {
      const count = col.length;
      col.length = 0;
      persistStorage();
      return { deletedCount: count };
    }
    const remaining = col.filter(item => !matchesFilter(item, filter));
    const deletedCount = col.length - remaining.length;
    col.length = 0;
    col.push(...remaining);
    persistStorage();
    return { deletedCount };
  }

  find(filter) {
    return new Query(this, 'find', filter);
  }

  findOne(filter) {
    return new Query(this, 'findOne', filter);
  }

  findById(id) {
    return new Query(this, 'findById', { _id: id });
  }

  countDocuments(filter) {
    return new Query(this, 'countDocuments', filter);
  }

  exists(filter) {
    return new Query(this, 'exists', filter);
  }

  async create(data) {
    if (Array.isArray(data)) {
      return this.insertMany(data);
    }
    this._checkUniqueIndexes(data);
    const doc = new Document(data, this);
    await doc.save();
    return doc;
  }

  async insertMany(docs) {
    const col = collections[this.modelName];
    const created = [];
    for (const d of docs) {
      this._checkUniqueIndexes(d);
      const doc = new Document(d, this);
      const obj = doc.toObject();
      if (!obj.createdAt) obj.createdAt = new Date();
      obj.updatedAt = new Date();
      col.push(obj);
      created.push(doc);
    }
    persistStorage();
    return created;
  }

  async findOneAndUpdate(filter, update, options = {}) {
    const col = collections[this.modelName];
    const match = col.find(item => matchesFilter(item, filter));

    if (!match && options.upsert) {
      const newObj = {
        _id: generateObjectId(),
        ...(filter._id ? { _id: filter._id } : {}),
        createdAt: new Date(),
        updatedAt: new Date(),
        ...(update.$set || update)
      };
      this._checkUniqueIndexes(newObj);
      col.push(newObj);
      persistStorage();
      return new Document(newObj, this);
    }

    if (!match) return null;

    if (update.$set) {
      Object.assign(match, update.$set);
    } else {
      Object.assign(match, update);
    }
    match.updatedAt = new Date();
    persistStorage();

    const doc = new Document(match, this);
    return doc;
  }

  async findByIdAndUpdate(id, update, options = {}) {
    return this.findOneAndUpdate({ _id: id }, update, options);
  }

  async findByIdAndDelete(id) {
    const col = collections[this.modelName];
    const idx = col.findIndex(x => String(x._id) === String(id) || String(x.id) === String(id));
    if (idx >= 0) {
      const [removed] = col.splice(idx, 1);
      persistStorage();
      return new Document(removed, this);
    }
    return null;
  }

  async updateMany(filter, update) {
    const col = collections[this.modelName];
    let count = 0;
    col.forEach(item => {
      if (matchesFilter(item, filter)) {
        if (update.$set) Object.assign(item, update.$set);
        else Object.assign(item, update);
        item.updatedAt = new Date();
        count++;
      }
    });
    persistStorage();
    return { matchedCount: count, modifiedCount: count };
  }
}

export const mongoose = {
  Schema,
  model: (name, schema) => {
    if (!models[name]) {
      models[name] = new Model(name, schema);
    }
    return models[name];
  },
  connect: async (uri, options) => {
    console.log(`[Mongoose Engine] Connected to database: ${uri}`);
    return true;
  },
  disconnect: async () => {
    persistStorage();
    return true;
  }
};

export default mongoose;
